import React from "react";
import { Switch, Route } from "react-router-dom";
import { Home } from "../pages/Home";

export const App = () => {
  console.log("APP RENDERED", { Home });

  if (!Home) {
    return <div style={{ color: "red" }}>Home is undefined</div>;
  }

  return (
    <Switch>
      <Route path="/" exact component={Home} />
    </Switch>
  );
};